-- V4.22: post-x14av multiphase Neumann outlet reconstruction, x8q ablation through x9c-outlet.
-- Documentary curation only. Historical x9a/x9b/x9c capillary milestones are NOT overwritten.
-- Colliding post-x14av labels are canonically suffixed only for database disambiguation, with raw historical labels preserved in notes/evidence.

INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8r-neumann-species','MILESTONE','x8r-neumann-species','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8r-neumann-species','0493x8r-neumann-species','x8r-neumann-species','0493x8r-neumann-species','post-x14av : Neumann multiphasique atomiseur','Variante x8r Neumann cinétique séparée par espèce','Remplace le bain cinétique x8q agrégé par un bain [cellule frontière][espèce] afin d''empêcher le mélange de type, masse, moment et température dans la continuation multiphasique.','EXPERIMENT','OPEN_BOUNDARY_MULTIPHASE','Tentative expérimentale post-x14av; construction et checks statiques PASS, mais la famille de reconstruction par bain reste non retenue après échec à l''arrivée de l''interface; supersédée par x8v.','A','2026-09-08',NULL,NULL,'La source historique s''auto-étiquette 0493x8r. Le suffixe canonique ''-neumann-species'' est une désambiguïsation documentaire V4.22 uniquement, nécessaire car 0493x8r désigne déjà l''outlet de pression Q6-g-f du cycle d''août.','Info/inputs/historical/README_x8r_neumann_multispecies_0493x8r.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8v','MILESTONE','x8v','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8v','0493x8v','x8v','0493x8v','post-x14av : Neumann multiphasique atomiseur','Réplique microscopique miroir pour Neumann cinétique','Teste une demi-population entrante construite par miroir géométrique de particules réelles proches de la face, sans fit Maxwellien ni bain agrégé.','EXPERIMENT','OPEN_BOUNDARY_MULTIPHASE','Prototype physics-first; checks de packaging PASS mais échec runtime précoce rapporté par x8w; non retenu, supersédé par x8w.','A','2026-09-08',NULL,NULL,'L''archive x8w indique explicitement qu''elle remplace les continuations x8q/x8r/x8v devenues instables dans le cas atomiseur multiphasique.','Info/inputs/historical/README_x8v_neumann_microscopic_replica_0493x8v.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8w','MILESTONE','x8w','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8w','0493x8w','x8w','0493x8w','post-x14av : Neumann multiphasique atomiseur','Cellules virtuelles statistiques Neumann','Génère par cellule de face et espèce des particules virtuelles extérieures à partir de l''état de la cellule physique adjacente, puis matérialise uniquement les trajectoires qui recroisent l''outlet.','EXPERIMENT','OPEN_BOUNDARY_MULTIPHASE','Échec expérimental documenté: la copie de l''occupation instantanée de la cellule de bord crée une couche de densité précoce; supersédé par x8x.','A','2026-09-08',NULL,NULL,'La mécanique de pool/synchronisation hôte reste volontairement non optimisée afin d''isoler la physique.','Info/inputs/historical/README_x8w_neumann_virtual_cells_0493x8w.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8x','MILESTONE','x8x','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8x','0493x8x','x8x','0493x8x','post-x14av : Neumann multiphasique atomiseur','Réservoir virtuel Neumann coarse-grained','Sépare support de phase local à la face et état macroscopique du réservoir: fraction d''espèce depuis la cellule frontière, densité et moments depuis un moyennage normal intérieur, population extérieure Poisson indépendante.','EXPERIMENT','OPEN_BOUNDARY_MULTIPHASE','Améliore le défaut x8w et passe les checks analytiques de demi-flux, mais la densité de réservoir suit encore le déficit de densité intérieur; supersédé par x8y.','A','2026-09-08',NULL,NULL,'Le test Monte-Carlo du package retrouve le demi-flux Maxwellien analytique; cela valide le sampler, pas la fermeture multiphasique globale.','Info/inputs/historical/README_x8x_neumann_virtual_reservoir_0493x8x.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8y','MILESTONE','x8y','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8y','0493x8y','x8y','0493x8y','post-x14av : Neumann multiphasique atomiseur','Réservoir de pression Neumann à densité de référence','Remplace la densité coarse-grained x8x par une occupation de référence Nref, tout en conservant support de phase de face et moments cinétiques coarse-grained par espèce.','EXPERIMENT','OPEN_BOUNDARY_MULTIPHASE','Échec post-contact documenté: un ux liquide intérieur négatif est recopié dans le Maxwellien extérieur et transforme le réservoir en injecteur macroscopique; supersédé par x8z.','A','2026-09-09',NULL,NULL,'Le diagnostic causal est formulé explicitement dans le README x8z sur le long run x8y.','Info/inputs/historical/README_x8y_neumann_pressure_reservoir_0493x8y.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x8z','MILESTONE','x8z','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x8z','0493x8z','x8z','0493x8z','post-x14av : Neumann multiphasique atomiseur','Clamp du backflow normal du réservoir Neumann','Impose u_n,ghost=max(u_n,interior,0) dans le repère de normale sortante afin d''interdire une injection macroscopique normale tout en conservant la variance thermique.','FIX','OPEN_BOUNDARY_MULTIPHASE','Correction partielle: le mode catastrophique normal est ciblé, mais le run 200x400 montre encore une propagation tangentielle du liquide à l''outlet; supersédé par x9a-neumann.','A','2026-09-09',NULL,NULL,'Le run x8z 200x400 conservé dans la provenance atteint 1500 pas et montre une population liquide très élevée et ux moyen négatif en fin de run; il s''agit d''un jalon de diagnostic/correction, pas d''une BC qualifiée.','Info/inputs/historical/README_x8z_neumann_pressure_reservoir_no_backflow_0493x8z.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x9a-neumann','MILESTONE','x9a-neumann','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x9a-neumann','0493x9a-neumann','x9a-neumann','0493x9a-neumann','post-x14av : Neumann multiphasique atomiseur','Annulation du drift complet du réservoir en backflow','Lorsque le coarse state indique un backflow, annule les deux composantes de vitesse moyenne du réservoir tout en conservant la variance thermique et donc les recroisements microscopiques Maxwelliens.','FIX','OPEN_BOUNDARY_MULTIPHASE','Correction partielle: supprime le mode backflow/sliding dominant, mais le test 200x400 laisse un obstacle cinétique résiduel à la sortie du liquide; supersédée par x9b-neumann.','A','2026-09-09',NULL,NULL,'Le log marker historique est [0493x9a-neumann]. Le suffixe ''-neumann'' est donc attesté et évite toute collision avec le x9a capillaire déjà canonique.','Info/inputs/historical/README_x9a_neumann_zero_tangential_drift_0493x9a.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x9b-neumann','MILESTONE','x9b-neumann','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x9b-neumann','0493x9b-neumann','x9b-neumann','0493x9b-neumann','post-x14av : Neumann multiphasique atomiseur','Réservoir gaz avec outflow liquide strict','Conserve le réservoir de pression x9a-neumann pour le gaz mais désactive toute génération de candidats virtuels pour le liquide; les particules liquides qui traversent l''outlet restent supprimées par le chemin physique crossing→inactive.','FIX','OPEN_BOUNDARY_MULTIPHASE','Amélioration forte du déchargement liquide sur 200x400 et 400x400, mais révèle un artefact topologique de type ''hachoir'': perte de support alpha au dernier maillon et création d''un end-cap artificiel; supersédée par x9c-outlet.','A','2026-09-09',NULL,NULL,'Le log marker historique est [0493x9b-neumann]. Le suffixe ''-neumann'' est conservé comme identifiant canonique pour ne pas écraser x9b courbure passive.','Info/inputs/historical/README_x9b_neumann_gas_reservoir_liquid_strict_outflow_0493x9b.txt',NULL);
INSERT OR IGNORE INTO objects(object_id,object_type,display_name,created_from) VALUES('milestone:0493x9c-outlet','MILESTONE','x9c-outlet','curation:0023_post_x14av_neumann_multiphase');
INSERT OR REPLACE INTO milestones(object_id,milestone_key,milestone_id,canonical_id,group_name,name,summary,nature,domain,status,confidence,introduced_date,introduced_commit,tag,notes,source_file,source_row) VALUES('milestone:0493x9c-outlet','0493x9c-outlet','x9c-outlet','0493x9c-outlet','post-x14av : Neumann multiphasique atomiseur','Prolongation du support de phase à l''outlet Neumann','Étend d''une cellule le support alpha liquide sur les cellules d''outlet segmenté Neumann par alpha_boundary=max(alpha_boundary,alpha_inward), sur x6c et x10-CIC, sans créer masse, quantité de mouvement ni énergie.','FIX','OPEN_BOUNDARY_MULTIPHASE','Candidat physics-first retenu après runs applicatifs 200x400 et 400x400: comportement de frontière jugé convaincant et réduction nette du hachage visuel; petites détachements résiduels possibles au 200x400, non évidents au 400x400. Qualification qualitative ciblée seulement; l''analyseur x14av reste DEMONSTRATION_DIAGNOSTIC_ONLY.','A','2026-09-09',NULL,NULL,'La source emploie explicitement ''0493x9c-outlet''/''0493X9C_OUTLET'' parce que x9c désigne déjà le sweep de courbure capillaire. La branche n''est pas présentée comme une qualification générale de toutes les sorties Neumann; l''optimisation de coût demandée ensuite n''est pas incluse faute d''artefact primaire complet dans ce bloc.','Info/inputs/historical/README_x9c_outlet_phase_continuation_0493x9c.txt',NULL);

UPDATE milestones SET notes=CASE WHEN notes IS NULL OR notes='' THEN 'V4.22 post-x14av: the air-assisted liquid/gas atomizer exposed that the historical x8q local-bath kinetic continuation is not a general multiphase outlet closure. The x8q-OFF ablation remains diagnostic only; the original x8q single-phase/open-boundary qualification is not retroactively invalidated.' ELSE notes || ' | ' || 'V4.22 post-x14av: the air-assisted liquid/gas atomizer exposed that the historical x8q local-bath kinetic continuation is not a general multiphase outlet closure. The x8q-OFF ablation remains diagnostic only; the original x8q single-phase/open-boundary qualification is not retroactively invalidated.' END WHERE object_id='milestone:0493x8q';
